  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build mutual reachability edges
    edges = []
    for u, v, d in distances:
        core_u = core_distance[u]
        core_v = core_distance[v]
        mut = max(core_u, core_v, d)
        # canonicalize order
        if u > v:
            u, v = v, u
        edges.append((u, v, mut))

    # Sort by weight, then endpoint IDs
    edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)

    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
